import {ninejName,ninejDefault,ninejPresets,ninejInputIds,ninejControls,readNineJPayload,bindNineJControls,ninejOutput,bindNineJOutput} from './su3-ninej-ui.js?v=20261026-electronic1';
import {cgName,cgDefault,cgPresets,cgInputIds,cgControls,readCGPayload,bindCGControls,cgOutput,bindCGOutput} from './su3-cg-ui.js?v=20261026-electronic1';
import {racahName,racahDefault,racahPresets,racahInputIds,racahControls,readRacahPayload,bindRacahControls,racahOutput,bindRacahOutput} from './su3-racah-ui.js?v=20261026-electronic1';
// Display-only helpers. Python supplies dynamics, CG coefficients, dimensions,
// Casimirs and weights; SVG only projects the returned coordinates and samples.
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=value=>Number.isFinite(Number(value))?Math.abs(Number(value))<1e-10?'0':Number(Number(value).toFixed(6)).toString():'—';
const half=value=>Number(value)%2===0?String(Number(value)/2):`${value}/2`;
const options=(items,value)=>items.map(([id,label])=>`<option value="${esc(id)}" ${String(id)===String(value)?'selected':''}>${esc(label)}</option>`).join('');
const number=(id,label,value,min,max,step='any')=>`<label>${label}<input id="${id}" type="number" value="${esc(value)}" min="${min}" max="${max}" step="${step}" required></label>`;
const probabilities=(items,label)=>`<div class="lg-probabilities lg-wide-probabilities">${items.map(item=>`<div><span>${esc(item.label)}</span><progress max="1" value="${esc(item.probability)}" aria-label="${esc(item.label+' '+label)}"></progress><code>${fmt(item.probability)}</code></div>`).join('')}</div>`;
const checks=(values,labels)=>`<div class="lg-checks">${Object.entries(labels).map(([key,label])=>`<div><span>${esc(label)}</span><code>${Number.isFinite(Number(values?.[key]))?Number(values[key]).toExponential(2):'—'}</code></div>`).join('')}</div>`;
const steps=values=>`<details class="lg-generator"><summary>核对本次计算的推导</summary><ol class="lg-calculation-steps">${(values||[]).map(value=>`<li>${esc(value)}</li>`).join('')}</ol></details>`;
export const physicsNames={rabi:'SU(2) · 两能级 Rabi 振荡',su2_coupling:'SU(2) · 自旋耦合与直积分解',su3_tensor:'SU(3) · 表示、权与直积分解',su3_cg:cgName,su3_racah:racahName,su3_ninej:ninejName};
export const physicsDefaults={rabi:{omega:1,delta:0,time:Math.PI},su2_coupling:{twoJ1:1,twoJ2:1,twoM1:1,twoM2:-1,coupling:1},su3_tensor:{p1:1,q1:0,p2:0,q2:1},su3_cg:cgDefault,su3_racah:racahDefault,su3_ninej:ninejDefault};
export function physicsControls(experiment,input){
  if(experiment==='su3_ninej')return ninejControls(input);
  if(experiment==='su3_racah')return racahControls(input);
  if(experiment==='su3_cg')return cgControls(input);
  if(experiment==='rabi')return `${number('lg-omega','驱动角频率 Ω',input.omega,0,10)}${number('lg-delta','失谐角频率 Δ',input.delta,-10,10)}${number('lg-time','演化时间 t',input.time,0,20)}<div class="lg-presets"><button type="button" data-lg-physics-preset="pi">共振 π 脉冲</button><button type="button" data-lg-physics-preset="2pi">共振 2π 脉冲</button><button type="button" data-lg-physics-preset="detuned">观察失谐</button></div><p class="lg-hint">取 ℏ = 1，H = (Ωσₓ + Δσ𝓏)/2，初态 |↑⟩。Ω、Δ 为同一时间单位的倒数；t 使用该时间单位。这里采用旋转框架中的有效两能级模型。</p>`;
  if(experiment==='su2_coupling')return [1,2].map(index=>`<label>第 ${index} 个角动量 j${index}<select id="lg-two-j${index}">${options(Array.from({length:7},(_,i)=>[i,`j${index} = ${half(i)}`]),input['twoJ'+index])}</select></label><label>乘积态磁量子数 m${index}<select id="lg-two-m${index}">${options(Array.from({length:input['twoJ'+index]+1},(_,i)=>{const m=input['twoJ'+index]-2*i;return[m,`m${index} = ${half(m)}`];}),input['twoM'+index])}</select></label>`).join('')+`${number('lg-coupling','交换常数 κ',input.coupling,-10,10)}<div class="lg-presets"><button type="button" data-lg-physics-preset="half-pair">1/2 ⊗ 1/2</button><button type="button" data-lg-physics-preset="half-one">1/2 ⊗ 1</button></div><p class="lg-hint">选择未耦合乘积态 |j₁m₁⟩|j₂m₂⟩，观察它在总角动量 |JM⟩ 基底中的展开。交换模型 H = κ J₁·J₂，取 ℏ = 1。</p>`;
  if(experiment==='su3_tensor')return [1,2].map(index=>`<label>第 ${index} 个表示的 Dynkin 标签 p${index}<select id="lg-p${index}">${options(Array.from({length:5},(_,i)=>[i,String(i)]),input['p'+index])}</select></label><label>第 ${index} 个表示的 Dynkin 标签 q${index}<select id="lg-q${index}">${options(Array.from({length:5},(_,i)=>[i,String(i)]),input['q'+index])}</select></label>`).join('')+`<div class="lg-presets"><button type="button" data-lg-physics-preset="three-three">3 ⊗ 3</button><button type="button" data-lg-physics-preset="three-bar">3 ⊗ 3̄</button><button type="button" data-lg-physics-preset="eight-eight">8 ⊗ 8</button></div><p class="lg-hint">每个输入表示满足 p + q ≤ 4。Python 按最高权逐项分解张量积；图中的重数是权空间维数。如需 CG 系数与换基，可切换到「CG 系数与换基」实验（其输入满足 p + q ≤ 4，并按计算模式限制总维数）。</p>`;
  return '';
}
export function readPhysicsPayload(experiment,$,read){
  if(experiment==='su3_ninej')return readNineJPayload($,read);
  if(experiment==='su3_racah')return readRacahPayload($,read);
  if(experiment==='su3_cg')return readCGPayload($,read);
  let input;
  if(experiment==='rabi')input={omega:read('#lg-omega',0,10),delta:read('#lg-delta',-10,10),time:read('#lg-time',0,20)};
  else if(experiment==='su2_coupling'){
    input={twoJ1:read('#lg-two-j1',0,6,true),twoJ2:read('#lg-two-j2',0,6,true),twoM1:read('#lg-two-m1',-6,6,true),twoM2:read('#lg-two-m2',-6,6,true),coupling:read('#lg-coupling',-10,10)};
    for(const index of [1,2])if(Math.abs(input['twoM'+index])>input['twoJ'+index]||(input['twoJ'+index]-input['twoM'+index])%2!==0)throw Error('磁量子数必须在 −j 到 j 之间，相邻取值相差 1。');
  }else{
    input={p1:read('#lg-p1',0,4,true),q1:read('#lg-q1',0,4,true),p2:read('#lg-p2',0,4,true),q2:read('#lg-q2',0,4,true)};
    if(input.p1+input.q1>4||input.p2+input.q2>4)throw Error('每个 SU(3) 输入表示需满足 p + q ≤ 4。');
  }
  return input;
}
export const physicsPresets={...cgPresets,...racahPresets,...ninejPresets,pi:{experiment:'rabi',input:{omega:1,delta:0,time:Math.PI}},'2pi':{experiment:'rabi',input:{omega:1,delta:0,time:2*Math.PI}},detuned:{experiment:'rabi',input:{omega:1,delta:2,time:Math.PI}},'half-pair':{experiment:'su2_coupling',input:{twoJ1:1,twoJ2:1,twoM1:1,twoM2:-1,coupling:1}},'half-one':{experiment:'su2_coupling',input:{twoJ1:1,twoJ2:2,twoM1:1,twoM2:0,coupling:1}},'three-three':{experiment:'su3_tensor',input:{p1:1,q1:0,p2:1,q2:0}},'three-bar':{experiment:'su3_tensor',input:{p1:1,q1:0,p2:0,q2:1}},'eight-eight':{experiment:'su3_tensor',input:{p1:1,q1:1,p2:1,q2:1}}};
export const physicsInputIds=[...cgInputIds,...racahInputIds,...ninejInputIds,'#lg-omega','#lg-delta','#lg-time','#lg-two-m1','#lg-two-m2','#lg-coupling','#lg-p1','#lg-q1','#lg-p2','#lg-q2'];

function trajectorySVG(trajectory,index){
  const xmax=Math.max(...trajectory.map(row=>row.time),1e-12),project=row=>[55+450*row.time/xmax,230-180*row.probability],points=trajectory.map(row=>project(row).join(',')).join(' '),row=trajectory[index]||trajectory.at(-1),point=project(row);
  return `<svg class="lg-visual lg-trajectory" viewBox="0 0 550 295" role="img" aria-label="随时间变化的跃迁概率"><title>Python 返回的两能级跃迁概率轨迹</title>${[0,.5,1].map(prob=>`<line x1="55" y1="${230-180*prob}" x2="505" y2="${230-180*prob}" stroke="#dce6d4"/><text x="43" y="${236-180*prob}" text-anchor="end" class="lg-svg-label">${prob}</text>`).join('')}<line x1="55" y1="230" x2="505" y2="230" stroke="#9caf8e"/><text x="55" y="255" class="lg-svg-label">0</text><text x="505" y="255" text-anchor="end" class="lg-svg-label">${fmt(trajectory.at(-1)?.time)}</text><text x="280" y="284" text-anchor="middle" class="lg-svg-label">时间 t</text><text x="55" y="24" class="lg-svg-label">P↓(t)</text><polyline points="${points}" fill="none" stroke="#5d8f52" stroke-width="3"/><line x1="${point[0]}" y1="45" x2="${point[0]}" y2="230" stroke="#bb893f" stroke-dasharray="5 4"/><circle cx="${point[0]}" cy="${point[1]}" r="6" fill="#bb893f" stroke="white" stroke-width="2"/></svg>`;
}
function sampleHTML(result,index){const row=result.trajectory[index]||result.trajectory.at(-1);return `${trajectorySVG(result.trajectory,index)}<p class="lg-sample-readout" role="status">t = <strong>${fmt(row.time)}</strong>，P↓ = <strong>${fmt(row.probability)}</strong><br>Bloch 向量 = (${row.blochVector.map(fmt).join(', ')})</p>`;}
function energySVG(levels){
  const values=levels.map(item=>item.energy),min=Math.min(...values),max=Math.max(...values),span=max-min||1;
  return `<svg class="lg-visual lg-energies" viewBox="0 0 550 ${Math.max(200,levels.length*54+60)}" role="img" aria-label="总角动量多重态的交换能量"><title>交换哈密顿量各总角动量多重态的能量</title>${levels.map((item,index)=>{const y=45+index*54,x=115+220*(item.energy-min)/span;return `<text x="12" y="${y+6}" class="lg-svg-label">J = ${esc(item.J)}</text><line x1="${x}" y1="${y}" x2="${x+75}" y2="${y}" stroke="#668e53" stroke-width="4"/><text x="${x+88}" y="${y+6}" class="lg-svg-label">${fmt(item.energy)}</text>`;}).join('')}<text x="12" y="${Math.max(190,levels.length*54+50)}" class="lg-svg-label">横向位置表示 E（各行按 J 分开）</text></svg>`;
}
function weightSVG(weights){
  const extent=Math.max(1,...weights.flatMap(item=>item.cartan.map(Math.abs))),scale=140/extent,project=([x,y])=>[210+scale*x,185-scale*y];
  return `<svg class="lg-visual lg-irrep-weights" viewBox="0 0 420 385" role="img" aria-label="SU(3) Cartan 权图；数字表示权的重数"><title>权图按 T₃、T₈ 相同尺度绘制，重合的权用重数标注</title><line x1="28" y1="185" x2="392" y2="185" stroke="#cbd8c0"/><line x1="210" y1="25" x2="210" y2="355" stroke="#cbd8c0"/><text x="382" y="210" class="lg-svg-label">T₃</text><text x="223" y="30" class="lg-svg-label">T₈</text>${weights.map(item=>{const point=project(item.cartan);return `<g><title>Dynkin 权 (${item.dynkin.join(', ')})；(T₃,T₈) = (${item.cartan.map(fmt).join(', ')})；重数 ${item.multiplicity}</title><circle cx="${point[0]}" cy="${point[1]}" r="${item.multiplicity>1?12:7}" fill="${item.multiplicity>1?'#b7873d':'#5e8b50'}" stroke="white" stroke-width="2"/>${item.multiplicity>1?`<text x="${point[0]}" y="${point[1]+5}" text-anchor="middle" class="lg-weight-count">${item.multiplicity}</text>`:''}</g>`;}).join('')}<text x="210" y="378" text-anchor="middle" class="lg-svg-label">两轴刻度相同；橙色权点的重数大于 1</text></svg>`;
}
function weightPanel(result,value='tensor'){
  const [kind,index]=value.split('-'),item=kind==='factor'?result.factors[Number(index)]:kind==='irrep'?result.decomposition[Number(index)]:null,weights=item?.weights||result.tensorWeights;
  return `${weightSVG(weights)}<p class="lg-visual-caption">${item?`(${item.p}, ${item.q}) · ${esc(item.label)}${kind==='irrep'&&item.multiplicity>1?`，在分解中出现 ${item.multiplicity} 份；图中展示其中一份。`:'。'}`:'完整张量积的权及其重数。'}权的重数与不可约表示在分解中出现的份数是两个不同概念。</p><details class="lg-generator"><summary>查看精确 Dynkin 权与重数表</summary><div class="lg-table-scroll"><table class="lg-data-table"><thead><tr><th>Dynkin 权</th><th>T₃</th><th>T₈</th><th>权的重数</th></tr></thead><tbody>${weights.map(weight=>`<tr><td>(${weight.dynkin.join(', ')})</td><td>${fmt(weight.cartan[0])}</td><td>${fmt(weight.cartan[1])}</td><td>${weight.multiplicity}</td></tr>`).join('')}</tbody></table></div></details>`;
}
export function physicsOutput(result){
  if(result.experiment==='su3_ninej')return ninejOutput(result);
  if(result.experiment==='su3_racah')return racahOutput(result);
  if(result.experiment==='su3_cg')return cgOutput(result);
  if(result.experiment==='rabi')return `<pre class="lg-formula">P↓(t) = Ω²/(Ω² + Δ²) · sin²(√(Ω² + Δ²)t/2)</pre><div id="lg-rabi-sample">${sampleHTML(result,result.trajectory.length-1)}</div><label class="lg-scrubber">沿计算轨迹观察 <input id="lg-trajectory-index" type="range" min="0" max="${result.trajectory.length-1}" step="1" value="${result.trajectory.length-1}" ${result.trajectory.length===1?'disabled':''} aria-label="查看计算轨迹的时间采样点"></label><p class="lg-visual-caption">拖动滑块读取 Python 已计算的时间采样点；曲线范围从 0 到设定时间 t。</p>${probabilities([{label:'↓（末态）',probability:result.transitionProbability}],'测量概率')}<div class="lg-state-facts"><p><span>有效角频率 √(Ω²+Δ²)</span><code>${fmt(result.omegaEffective)}</code></p><p><span>最大可达跃迁概率</span><code>${fmt(result.maxTransitionProbability)}</code></p><p><span>概率振荡周期</span><code>${result.periodProbability===null?'无振荡或周期超出数值范围':fmt(result.periodProbability)}</code></p></div>${checks(result.checks,{stateNorm:'态归一化残差',unitarity:'幺正残差',determinant:'行列式残差',probabilityFormula:'概率公式残差'})}${steps(result.derivation)}`;
  if(result.experiment==='su2_coupling')return `<pre class="lg-formula">${esc(result.decomposition.map(item=>`J = ${item.J}（${item.dimension} 维）`).join(' ⊕ '))}</pre><p>乘积空间共 ${result.dimension} 维。下面展开选定的 ${esc(result.selected.label)}，总 M = ${esc(result.selected.M)}。</p>${probabilities(result.selected.expansion.map(item=>({label:`J = ${item.J}`,probability:item.probability})),'测得该总角动量的概率')}<div class="lg-table-scroll"><table class="lg-data-table"><caption>选定乘积态在耦合基底中的展开</caption><thead><tr><th>|J, M⟩</th><th>CG 振幅</th><th>概率</th></tr></thead><tbody>${result.selected.expansion.map(item=>`<tr><td>|${esc(item.J)}, ${esc(item.M)}⟩</td><td>${fmt(item.coefficient)}</td><td>${fmt(item.probability)}</td></tr>`).join('')}</tbody></table></div><details class="lg-generator"><summary>查看对应的耦合态如何由乘积态组成</summary>${result.selected.expansion.map(item=>`<p class="lg-mono">|J = ${esc(item.J)}, M = ${esc(item.M)}⟩ = ${item.terms.map(term=>`${fmt(term.coefficient)} |${esc(term.m1)}, ${esc(term.m2)}⟩`).join(' + ')}</p>`).join('')}<p class="lg-hint">此处 |m₁,m₂⟩ 省略固定的 j₁,j₂。振幅的符号取决于基底相位约定；概率不受整体相位选择影响。</p></details><h4>交换相互作用的多重态能量</h4><pre class="lg-formula">Eⱼ = κ [J(J+1) − j₁(j₁+1) − j₂(j₂+1)] / 2</pre>${energySVG(result.decomposition)}<div class="lg-table-scroll"><table class="lg-data-table"><thead><tr><th>总 J</th><th>维数</th><th>J² 本征值</th><th>交换能量</th></tr></thead><tbody>${result.decomposition.map(item=>`<tr><td>${esc(item.J)}</td><td>${item.dimension}</td><td>${fmt(item.casimir)}</td><td>${fmt(item.energy)}</td></tr>`).join('')}</tbody></table></div>${checks(result.checks,{dimension:'维数核对残差',orthogonality:'CG 正交残差',casimir:'Casimir 本征残差',probability:'概率和残差'})}${steps(result.derivation)}`;
  return `<pre class="lg-formula">${esc(result.decompositionText)}</pre><p>张量积总维数 ${result.dimension}。Dynkin 标签 (p, q) 唯一指明不可约表示；同维数不一定意味着同一表示。</p><div class="lg-table-scroll"><table class="lg-data-table"><caption>不可约表示分解与二次 Casimir</caption><thead><tr><th>(p, q)</th><th>表示</th><th>份数</th><th>每份维数</th><th>C₂</th></tr></thead><tbody>${result.decomposition.map(item=>`<tr><td>(${item.p}, ${item.q})</td><td>${esc(item.label)}</td><td>${item.multiplicity}</td><td>${item.dimension}</td><td>${fmt(item.casimir)}</td></tr>`).join('')}</tbody></table></div><label class="lg-filter">选择权图<select id="lg-weight-view">${options([['tensor','完整张量积'],...result.factors.map((item,i)=>['factor-'+i,`输入 ${i+1}：(${item.p},${item.q}) ${item.label}`]),...result.decomposition.map((item,i)=>['irrep-'+i,`分量：(${item.p},${item.q}) ${item.label}，${item.multiplicity} 份`])],'tensor')}</select></label><div id="lg-weight-panel">${weightPanel(result)}</div><p class="lg-hint">本实验展示表示和权的精确组合分解；未计算 SU(3) CG 系数。相位、换基及 8 ⊗ 8 中的对称／反对称副本可在「CG 系数与换基」实验中探索。</p><details class="lg-generator"><summary>查看最高权逐项减去的过程</summary><ol>${result.steps.map(item=>`<li>减去 ${item.multiplicity} 份 (${item.p},${item.q}) ${esc(item.label)} 后，剩余总维数 ${item.remainingDimension}。</li>`).join('')}</ol></details>${checks(result.checks,{dimension:'维数核对残差',weightMultiplicity:'权的重数核对残差',character:'特征标核对残差'})}${steps(result.derivation)}`;
}
export function bindPhysicsControls(experiment,root,current){if(experiment==='su3_ninej')bindNineJControls(root,current);if(experiment==='su3_cg')bindCGControls(root,current);if(experiment==='su3_racah')bindRacahControls(root,current);}
export function bindPhysicsOutput(root,result,current,runWithInput){
  if(result.experiment==='su3_ninej'){bindNineJOutput(root,result,current,runWithInput);return;}
  if(result.experiment==='su3_racah'){bindRacahOutput(root,result,current,runWithInput);return;}
  if(result.experiment==='su3_cg'){bindCGOutput(root,result,current,runWithInput);return;}
  const slider=root.querySelector('#lg-trajectory-index');if(slider)slider.oninput=()=>{if(!current())return;const index=Number(slider.value);if(Number.isInteger(index)&&index>=0&&index<result.trajectory.length)root.querySelector('#lg-rabi-sample').innerHTML=sampleHTML(result,index);};
  const selector=root.querySelector('#lg-weight-view');if(selector)selector.onchange=()=>{if(!current())return;const allowed=['tensor',...result.factors.map((_,i)=>'factor-'+i),...result.decomposition.map((_,i)=>'irrep-'+i)];if(allowed.includes(selector.value))root.querySelector('#lg-weight-panel').innerHTML=weightPanel(result,selector.value);};
}
